begin;
insert into auth.users(id,email,raw_user_meta_data,raw_app_meta_data,aud,role,encrypted_password,email_confirmed_at,created_at,updated_at)select('fce10000-0000-4000-8000-'||lpad(x::text,12,'0'))::uuid,'synthetic-affiliation-'||x||'@fixture.invalid',jsonb_build_object('full_name','Affiliation fixture','account_type_request','EXTERNAL'),'{}','authenticated','authenticated','fixture-no-password',now(),now(),now()from generate_series(1,3)x;
insert into auth.sessions(id,user_id)select('fce20000-0000-4000-8000-'||lpad(x::text,12,'0'))::uuid,('fce10000-0000-4000-8000-'||lpad(x::text,12,'0'))::uuid from generate_series(1,3)x;
insert into cbgpu_schools.schools(id,official_name,normalized_name,display_name,type,region,configuration,features,status)values('fixture-affiliation-b','Affiliation B','affiliation b','Affiliation B','HIGH_SCHOOL','Synthetic','{"student_id_policy":"SCHOOL_DEFINED"}',array['materials','community','projects','contests'],'APPROVED');
insert into cbgpu_schools.memberships(user_id,school_id,membership_type,status,verified,school_roles)values('fce10000-0000-4000-8000-000000000001','fixture-affiliation-b','EXTERNAL','ACTIVE',true,array['SCHOOL_OWNER','SCHOOL_ADMIN']),('fce10000-0000-4000-8000-000000000002','fixture-affiliation-b','TEACHER','ACTIVE',true,array['SCHOOL_ADMIN']),('fce10000-0000-4000-8000-000000000003','fixture-affiliation-b','STUDENT','ACTIVE',true,'{}');
update cbgpu_schools.memberships set student_number='B007',student_number_school_year=extract(year from now())::integer where user_id='fce10000-0000-4000-8000-000000000003'and school_id='fixture-affiliation-b';
select set_config('request.jwt.claims','{"role":"service_role"}',true);update public.profiles set is_admin=true where id in('fce10000-0000-4000-8000-000000000001','fce10000-0000-4000-8000-000000000003');
select set_config('request.jwt.claims','{"sub":"fce10000-0000-4000-8000-000000000001","role":"authenticated","session_id":"fce20000-0000-4000-8000-000000000001"}',true);set local role authenticated;
create temp table aff_request as select public.cbgpu_school_affiliation_api('create','{"school_id":"fixture-affiliation-b","membership_type":"TEACHER","name":"Synthetic founder teacher","department":"Science","reason":"Independent teacher verification requested","consent":true}')value;
do $$begin begin perform public.cbgpu_school_affiliation_api('review',jsonb_build_object('id',(select value#>>'{request,id}'from aff_request),'revision',1,'decision','APPROVE','confirmed',true));raise exception 'PLATFORM_SELF_APPROVAL_ALLOWED';exception when insufficient_privilege then null;end;begin perform count(*)from cbgpu_schools.affiliation_requests;raise exception 'PRIVATE_AFFILIATION_CONTEXT_PUBLIC';exception when insufficient_privilege then null;end;end$$;
reset role;select set_config('request.jwt.claims','{"role":"service_role"}',true);update public.profiles set is_admin=false where id='fce10000-0000-4000-8000-000000000001';
do $$begin if not exists(select 1 from cbgpu_schools.memberships where user_id='fce10000-0000-4000-8000-000000000001'and school_id='fixture-affiliation-b'and membership_type='EXTERNAL'and status='ACTIVE'and verified and school_roles=array['SCHOOL_OWNER','SCHOOL_ADMIN'])then raise exception 'PENDING_CHANGED_FOUNDER';end if;end$$;
select set_config('request.jwt.claims','{"sub":"fce10000-0000-4000-8000-000000000002","role":"authenticated","session_id":"fce20000-0000-4000-8000-000000000002"}',true);set local role authenticated;
select public.cbgpu_school_affiliation_api('review',jsonb_build_object('id',(select value#>>'{request,id}'from aff_request),'revision',1,'decision','APPROVE','confirmed',true));
reset role;do $$begin if not exists(select 1 from cbgpu_schools.memberships where user_id='fce10000-0000-4000-8000-000000000001'and school_id='fixture-affiliation-b'and membership_type='TEACHER'and status='ACTIVE'and verified and school_roles@>array['SCHOOL_OWNER','SCHOOL_ADMIN'])or not exists(select 1 from public.profiles where id='fce10000-0000-4000-8000-000000000001'and account_type='EXTERNAL'and not is_admin and not is_approved)then raise exception 'TEACHER_SCOPE_OR_GLOBAL_PROMOTION';end if;if cbgpu_accounts.can_user_use_resource('fce10000-0000-4000-8000-000000000001','gpu','cbsh')then raise exception 'TEACHER_GRANTED_CBSH_GPU';end if;end$$;
select set_config('request.jwt.claims','{"sub":"fce10000-0000-4000-8000-000000000001","role":"authenticated","session_id":"fce20000-0000-4000-8000-000000000001"}',true);set local role authenticated;
do $$begin begin perform public.cbgpu_school_affiliation_api('create',jsonb_build_object('school_id','fixture-affiliation-b','membership_type','STUDENT','student_number','B007','school_year',extract(year from now())::integer,'name','Synthetic Student','reason','Student verification','consent',true));raise exception 'DUPLICATE_NUMBER_REQUEST';exception when unique_violation then null;end;end$$;
create temp table aff_student as select public.cbgpu_school_affiliation_api('create',jsonb_build_object('school_id','fixture-affiliation-b','membership_type','STUDENT','student_number','B008','school_year',extract(year from now())::integer,'name','Synthetic Student','reason','Student verification','consent',true))value;
select set_config('request.jwt.claims','{"sub":"fce10000-0000-4000-8000-000000000003","role":"authenticated","session_id":"fce20000-0000-4000-8000-000000000003"}',true);
do $$begin begin perform public.cbgpu_school_affiliation_api('review',jsonb_build_object('id',(select value#>>'{request,id}'from aff_student),'revision',9,'decision','APPROVE','confirmed',true));raise exception 'STALE_AFFILIATION_REVIEW';exception when serialization_failure then null;end;end$$;
reset role;update cbgpu_schools.memberships set status='SUSPENDED'where user_id='fce10000-0000-4000-8000-000000000001'and school_id='fixture-affiliation-b';set local role authenticated;
do $$begin begin perform public.cbgpu_school_affiliation_api('review',jsonb_build_object('id',(select value#>>'{request,id}'from aff_student),'revision',1,'decision','APPROVE','confirmed',true));raise exception 'SUSPENDED_AFFILIATION_APPROVED';exception when insufficient_privilege then null;end;end$$;
reset role;update cbgpu_schools.memberships set status='ACTIVE'where user_id='fce10000-0000-4000-8000-000000000001'and school_id='fixture-affiliation-b';set local role authenticated;
select public.cbgpu_school_affiliation_api('review',jsonb_build_object('id',(select value#>>'{request,id}'from aff_student),'revision',1,'decision','APPROVE','confirmed',true));
reset role;do $$begin if not exists(select 1 from cbgpu_schools.memberships where user_id='fce10000-0000-4000-8000-000000000001'and school_id='fixture-affiliation-b'and membership_type='STUDENT'and student_number='B008'and school_roles@>array['SCHOOL_OWNER','SCHOOL_ADMIN'])then raise exception 'STUDENT_CHANGE_LOST_OWNER_OR_NUMBER';end if;end$$;
rollback;
select 'AFFILIATION_CHANGE_TESTS_PASSED';
